{
  "project_id": "b38b34acafef4c929cd5",
  "name": "create_concurrent_job_queue",
  "query": "create schema if not exists private;

create table if not exists private.job_queue (
  id uuid primary key default gen_random_uuid(),
  payload jsonb not null,
  status text not null default 'pending' check (status in ('pending', 'processing', 'completed', 'failed')),
  attempts integer not null default 0 check (attempts >= 0),
  available_at timestamptz not null default now(),
  locked_at timestamptz,
  locked_by text,
  completed_at timestamptz,
  last_error text,
  created_at timestamptz not null default now()
);

create index if not exists job_queue_claim_idx
  on private.job_queue (available_at, created_at)
  where status = 'pending';

create or replace function private.enqueue_job(p_payload jsonb, p_available_at timestamptz default now())
returns uuid
language sql
security invoker
set search_path = private, pg_catalog
as $$
  insert into private.job_queue (payload, available_at)
  values (p_payload, p_available_at)
  returning id;
$$;

create or replace function private.claim_jobs(
  p_worker_id text,
  p_batch_size integer default 10,
  p_visibility_timeout_seconds integer default 300
)
returns setof private.job_queue
language plpgsql
security invoker
set search_path = private, pg_catalog
as $$
begin
  if p_worker_id is null or length(trim(p_worker_id)) = 0 then
    raise exception 'worker_id must not be empty';
  end if;
  if p_batch_size < 1 or p_batch_size > 1000 then
    raise exception 'batch_size must be between 1 and 1000';
  end if;
  if p_visibility_timeout_seconds < 1 then
    raise exception 'visibility timeout must be positive';
  end if;

  return query
  with claimed as (
    select q.id
    from private.job_queue q
    where q.status = 'pending'
      and q.available_at <= now()
    order by q.created_at, q.id
    for update skip locked
    limit p_batch_size
  )
  update private.job_queue q
  set status = 'processing',
      attempts = q.attempts + 1,
      locked_at = now(),
      locked_by = p_worker_id,
      available_at = now() + make_interval(secs => p_visibility_timeout_seconds)
  from claimed
  where q.id = claimed.id
  returning q.*;
end;
$$;

create or replace function private.complete_job(p_job_id uuid, p_worker_id text)
returns boolean
language sql
security invoker
set search_path = private, pg_catalog
as $$
  update private.job_queue
  set status = 'completed', completed_at = now(), locked_at = null, locked_by = null
  where id = p_job_id and status = 'processing' and locked_by = p_worker_id
  returning true;
$$;

create or replace function private.fail_job(p_job_id uuid, p_worker_id text, p_error text, p_retry_delay_seconds integer default 60)
returns boolean
language sql
security invoker
set search_path = private, pg_catalog
as $$
  update private.job_queue
  set status = 'pending', available_at = now() + make_interval(secs => greatest(p_retry_delay_seconds, 0)),
      locked_at = null, locked_by = null, last_error = left(p_error, 4000)
  where id = p_job_id and status = 'processing' and locked_by = p_worker_id
  returning true;
$$;

revoke all on schema private from public;
revoke all on all tables in schema private from public;
revoke all on all functions in schema private from public;
grant usage on schema private to service_role;
grant select, insert, update on private.job_queue to service_role;
grant execute on function private.enqueue_job(jsonb, timestamptz) to service_role;
grant execute on function private.claim_jobs(text, integer, integer) to service_role;
grant execute on function private.complete_job(uuid, text) to service_role;
grant execute on function private.fail_job(uuid, text, text, integer) to service_role;"
}

